CREATE TABLE SYS_ROLE_PERMISSION
(
    ID VARCHAR2(64) NOT NULL ENABLE,
    ROLE_ID VARCHAR2(64),
    PERMISSION_ID VARCHAR2(64),
    DATA_RULE_IDS VARCHAR2(2000),
    OPERATE_DATE TIMESTAMP (3),
    OPERATE_IP VARCHAR2(40),
    TENANT_CODE VARCHAR2(32),
    PRIMARY KEY (id)
) ;
comment on table SYS_ROLE_PERMISSION is '角色按钮菜单权限表';
comment on column SYS_ROLE_PERMISSION.id is '主键ID';


